package com.ferreteriahuaman.integration;
import com.ferreteriahuaman.service.*;import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.dto.CashModels.*;import com.ferreteriahuaman.security.AuthModels.Identity;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional @EnabledIfEnvironmentVariable(named="HUAMAN_DB_INTEGRATION",matches="true")
class CashDatabaseTest {
 @Autowired ProductService products;@Autowired CatalogService catalog;@Autowired CashService service;@Autowired AuthStore auth;@Autowired Environment env;@Autowired JdbcTemplate jdbc;Identity actor;BigDecimal n(String s){return new BigDecimal(s);}
 @BeforeEach void setup(){Assumptions.assumeTrue(jdbc.queryForObject("select count(*) from huaman.caja_diaria where estado_caja='ABIERTA' or fecha=timezone('America/Lima',now())::date",Long.class)==0,"No interferir con cajas reales existentes");var u=auth.lockUsername(env.getRequiredProperty("BOOTSTRAP_ADMIN_USUARIO")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");UUID token=UUID.randomUUID();auth.createSession(u.id(),token,LocalDateTime.now(ZoneId.of("America/Lima")));actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),token,OffsetDateTime.now().plusMinutes(30));}
 long open(String amount){return service.open(actor,"INTEGRATION_ROLLBACK",new Open(n(amount),"Prueba transaccional de caja",UUID.randomUUID())).id();}
 @Test void zeroOpeningCreatesNoMovementAndRetryDoesNotDuplicate(){var request=new Open(n("0"),null,UUID.randomUUID());long id=service.open(actor,"INTEGRATION_ROLLBACK",request).id();assertThat(service.open(actor,"INTEGRATION_ROLLBACK",request).id()).isEqualTo(id);assertThat(service.current().caja().id()).isEqualTo(id);assertThat(service.movements(id,0,20).total()).isZero();assertThat(service.get(id).efectivo()).isEqualTo("0");}
 @Test void manualMovementsAndCloseReconcileExactlyAndAreIdempotent(){long id=open("100.25");var income=new Manual("INGRESO_MANUAL",n("20.10"),"Ingreso de cambio registrado",UUID.randomUUID());long movement=service.manual(actor,"INTEGRATION_ROLLBACK",id,income).id();assertThat(service.manual(actor,"INTEGRATION_ROLLBACK",id,income).id()).isEqualTo(movement);service.manual(actor,"INTEGRATION_ROLLBACK",id,new Manual("EGRESO_MANUAL",n("10.05"),"Pago de gasto documentado",UUID.randomUUID()));assertThat(service.get(id).efectivo()).isEqualTo("110.30");assertThat(service.movements(id,0,20).total()).isEqualTo(3);var close=new Close(n("110.30"),n("0"),n("0"),null,UUID.randomUUID());assertThat(service.close(actor,"INTEGRATION_ROLLBACK",id,close).id()).isEqualTo(id);assertThat(service.close(actor,"INTEGRATION_ROLLBACK",id,close).id()).isEqualTo(id);var c=service.get(id);assertThat(c.estado()).isEqualTo("CERRADA");assertThat(c.diferenciaEfectivo()).isEqualTo("0.00");assertThat(service.history(c.fecha(),c.fecha(),"CERRADA",0,20).total()).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from huaman.bitacora_evento where pccre='INTEGRATION_ROLLBACK' and accion like 'CAJ.%'",Long.class)).isEqualTo(4);}
 @Test void overdraftIsRejected(){long id=open("10");assertThatThrownBy(()->service.manual(actor,"INTEGRATION_ROLLBACK",id,new Manual("EGRESO_MANUAL",n("10.01"),"Egreso fuera del saldo actual",UUID.randomUUID()))).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void discrepancyRequiresObservation(){long id=open("10");assertThatThrownBy(()->service.close(actor,"INTEGRATION_ROLLBACK",id,new Close(n("9"),n("0"),n("0"),null,UUID.randomUUID()))).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void justifiedDiscrepancyIsPreservedAndClosedRegisterCannotReceiveMoney(){long id=open("10");service.close(actor,"INTEGRATION_ROLLBACK",id,new Close(n("9"),n("0"),n("0"),"Diferencia identificada en arqueo",UUID.randomUUID()));assertThat(service.get(id).diferenciaEfectivo()).isEqualTo("-1.00");assertThatThrownBy(()->service.manual(actor,"INTEGRATION_ROLLBACK",id,new Manual("INGRESO_MANUAL",n("1"),"Ingreso luego de haber cerrado",UUID.randomUUID()))).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void secondOpeningOnSameDateIsRejected(){open("0");assertThatThrownBy(()->open("5")).isInstanceOf(org.springframework.dao.DataAccessException.class);}

 @Test void closedRegisterCannotBeOpenedAgainOnSameDate(){long id=open("0");service.close(actor,"INTEGRATION_ROLLBACK",id,new Close(n("0"),n("0"),n("0"),null,UUID.randomUUID()));assertThatThrownBy(()->open("0")).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void pendingSaleBlocksClosing(){long id=open("0");String unique="INTEGRACION_"+UUID.randomUUID().toString().substring(0,8).toUpperCase();long category=catalog.createCategory(actor,"INTEGRATION_ROLLBACK",new com.ferreteriahuaman.dto.CatalogModels.CategoryInput(unique,null,null)).id();long unit=jdbc.queryForObject("select id_unidad from huaman.unidad_medida where codigo_sunat='NIU'",Long.class);var product=products.create(actor,"INTEGRATION_ROLLBACK",new com.ferreteriahuaman.dto.ProductModels.ProductInput(unique,"Producto temporal",null,category,unit,false,n("1"),n("1"),"GRANEL",n("0"),null,"Unidad",n("10"),null));long presentation=products.details(actor,product.id()).presentaciones().getFirst().id();long sale=jdbc.queryForObject("insert into huaman.venta(id_caja,id_vendedor,clave_idempotencia) values(?,?,?) returning id_venta",Long.class,id,actor.id(),UUID.randomUUID());jdbc.update("insert into huaman.detalle_venta(id_venta,id_producto,id_presentacion,cantidad) values(?,?,?,1)",sale,product.id(),presentation);assertThat(service.get(id).ventasPendientes()).isEqualTo(1);assertThatThrownBy(()->service.close(actor,"INTEGRATION_ROLLBACK",id,new Close(n("0"),n("0"),n("0"),null,UUID.randomUUID()))).isInstanceOf(org.springframework.dao.DataAccessException.class);}
}
